            <td class="px dm-card" style="padding:0 40px; background-color:#ffffff;">
              <table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0"><tr><td style="border-top:1px solid #e5e7eb; font-size:0; line-height:0;">&nbsp;</td></tr></table>
            </td>
          </tr>
          <tr><td class="dm-card" style="height:28px; line-height:28px; font-size:0; background-color:#ffffff;">&nbsp;</td></tr>
          <tr>
            <td class="px dm-card" style="padding:0 40px 32px; background-color:#ffffff; font-size:0; text-align:center;">
              <!--[if mso]><table role="presentation" width="520" cellpadding="0" cellspacing="0" border="0"><tr><![endif]-->
                <!--[if mso]><td width="260" valign="top"><![endif]-->
                <div class="stack" style="display:inline-block; width:100%; max-width:260px; vertical-align:top; text-align:left; margin:0 0 0 0;">
                  <table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0">
                    <tr><td class="stack-pad" style="padding:0 0 0 0; font-family:Arial, Helvetica, sans-serif; font-size:15px; line-height:23px; color:#374151;">
                      <img src="https://placehold.co/260x150/ccfbf1/0f766e/png?text=Dark%20mode" width="260" alt="Dark mode article" class="fluid" style="display:block; width:100%; max-width:260px; height:auto; border-radius:6px; margin:0 0 14px;">
