insert into public.email_templates (id, user_id, category_id, name, description, html, tags, is_system)
  values ('30ebad43-af90-5f7f-a3e6-6f81aa07ce88', null, (select id from public.template_categories where slug = 'newsletter'), 'Newsletter – minimal text', 'Text-first newsletter: no images required, readable with images blocked.', $mc$<!DOCTYPE html>
<html lang="en" xmlns="http://www.w3.org/1999/xhtml" xmlns:v="urn:schemas-microsoft-com:vml" xmlns:o="urn:schemas-microsoft-com:office:office">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <meta name="x-apple-disable-message-reformatting">
  <meta name="format-detection" content="telephone=no, date=no, address=no, email=no">
  <meta name="color-scheme" content="light dark">
  <meta name="supported-color-schemes" content="light dark">
  <title>Notes from the team</title>
  <!--[if mso]>
  <noscript><xml><o:OfficeDocumentSettings><o:PixelsPerInch>96</o:PixelsPerInch></o:OfficeDocumentSettings></xml></noscript>
  <![endif]-->
  <style>
    body { margin: 0; padding: 0; width: 100% !important; -webkit-text-size-adjust: 100%; -ms-text-size-adjust: 100%; }
    table, td { border-collapse: collapse; mso-table-lspace: 0pt; mso-table-rspace: 0pt; }
    img { border: 0; height: auto; line-height: 100%; outline: none; text-decoration: none; -ms-interpolation-mode: bicubic; }
    a[x-apple-data-detectors] { color: inherit !important; text-decoration: none !important; }
    @media only screen and (max-width: 620px) {
      .container { width: 100% !important; }
      .px { padding-left: 20px !important; padding-right: 20px !important; }
      .stack { display: block !important; width: 100% !important; max-width: 100% !important; }
      .stack-pad { padding: 0 0 20px 0 !important; }
      .fluid { width: 100% !important; max-width: 100% !important; height: auto !important; }
      .center-m { text-align: center !important; }
      .h1-m { font-size: 26px !important; line-height: 34px !important; }
    }
    @media (prefers-color-scheme: dark) {
      .dm-bg { background-color: #16181d !important; }
      .dm-card { background-color: #1f2229 !important; }
      .dm-text { color: #e6e8ee !important; }
      .dm-muted { color: #a7adba !important; }
    }
    [data-ogsc] .dm-text { color: #e6e8ee !important; }
  </style>
</head>
<body class="dm-bg" style="margin:0; padding:0; background-color:#ffffff;">
  <div style="display:none; max-height:0; max-width:0; overflow:hidden; mso-hide:all; font-size:1px; line-height:1px; color:#ffffff;">Three things we learned this month.&#8199;&#65279;&#847;&#8199;&#65279;&#847;&#8199;&#65279;&#847;&#8199;&#65279;&#847;</div>
  <table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" class="dm-bg" style="background-color:#ffffff;">
    <tr>
      <td align="center" style="padding:24px 12px;">
        <!--[if mso]><table role="presentation" width="600" cellpadding="0" cellspacing="0" border="0" align="center"><tr><td><![endif]-->
        <table role="presentation" class="container" width="600" cellpadding="0" cellspacing="0" border="0" style="width:600px; max-width:600px;">
          <tr>
            <td class="px dm-card dm-text" style="padding:32px 40px 8px; background-color:#ffffff; font-family:Arial, Helvetica, sans-serif; font-size:16px; line-height:26px; color:#374151;">
              <p class="dm-muted" style="margin:0; font-size:13px; letter-spacing:1px; text-transform:uppercase; color:#6b7280;">Notes from the team &middot; November</p>
            </td>
          </tr>
          <tr>
            <td class="px dm-card dm-text" style="padding:0 40px 32px; background-color:#ffffff; font-family:Arial, Helvetica, sans-serif; font-size:16px; line-height:26px; color:#374151;">
              <h1 class="h1-m dm-text" style="margin:0 0 20px; font-size:28px; line-height:36px; color:#111827;">Three things we learned this month</h1>
              <p style="margin:0 0 16px;"><strong>Shorter subject lines won.</strong> Under 40 characters improved opens across every segment we tested.</p>
              <p style="margin:0 0 16px;"><strong>Live text beats images.</strong> Emails that put key messages in HTML text kept working when images were blocked.</p>
              <p style="margin:0 0 16px;"><strong>Accessibility is everyone's job.</strong> Semantic headings and real alt text took ten minutes and helped every reader.</p>
              <p style="margin:0;">— The Northwind team</p>
            </td>
          </tr>
          <tr>
            <td class="px" align="center" style="padding:32px 40px; background-color:#ffffff; font-family:Arial, Helvetica, sans-serif; font-size:12px; line-height:18px; color:#6b7280;">
              <p class="dm-muted" style="margin:0 0 8px;">Northwind Inc. &middot; 123 Market Street, San Francisco, CA 94105</p>
              <p class="dm-muted" style="margin:0;">You're receiving this email because you signed up at example.com.<br>
                <a href="https://example.com/unsubscribe" style="color:#6b7280; text-decoration:underline;">Unsubscribe</a> &middot; <a href="https://example.com/preferences" style="color:#6b7280; text-decoration:underline;">Email preferences</a></p>
            </td>
          </tr>
        </table>
        <!--[if mso]></td></tr></table><![endif]-->
      </td>
    </tr>
  </table>
</body>
</html>
$mc$, array['newsletter', 'plain', 'accessible']::text[], true)
  on conflict (id) do update set category_id = excluded.category_id, name = excluded.name, description = excluded.description, html = excluded.html, tags = excluded.tags;

